<?php require_once __DIR__ . '/auth.php'; require_login('admin');$students=many('SELECT u.id,u.name,u.email,s.university,s.course,s.semester,COALESCE(SUM(qa.questions_count),0) solved,COALESCE(ROUND(AVG(qa.accuracy)),0) accuracy FROM users u JOIN students s ON s.user_id=u.id LEFT JOIN quiz_attempts qa ON qa.user_id=u.id WHERE u.role=\'student\' GROUP BY u.id ORDER BY u.created_at DESC');$pageTitle='Manage students';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">People directory</div><h1>Students.</h1><p>Review each learner’s profile, progress, and verified signal.</p></div></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>University</th><th>Course</th><th>Progress</th><th></th></tr></thead><tbody><?php foreach($students as $student):?><tr><td><strong><?=e($student['name'])?></strong><small style="display:block;color:var(--muted)"><?=e($student['email'])?></small></td><td><?=e($student['university'])?></td><td><?=e($student['course'])?><small style="display:block;color:var(--muted)"><?=e($student['semester'])?></small></td><td><?=$student['solved']?> solved · <?=$student['accuracy']?>%</td><td><a class="text-link" href="student_profile.php?id=<?=$student['id']?>">View →</a></td></tr><?php endforeach;?></tbody></table></div></section><?php include 'includes/footer.php';?>